mapper.select:
SELECT p.id, p.member_id, pc.name AS category_name, p.title, p.content, p.status, p.blocked_reason, p.blocked_at, p.blocked_by, p.view_count, p.like_count, p.created_at, p.updated_at
FROM posts p JOIN post_categories pc ON pc.id = p.category_id
WHERE p.id = #{postId}

mapper.update:
UPDATE post_reports pr
SET pr.status = #{status}
WHERE pr.post_id = #{postId}
AND pr.status = 'PENDING'
